import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { booksAPI } from '../utils/api';
import { clearUserSession, getStoredUser } from '../utils/session';

const LandingPage = () => {
  const navigate = useNavigate();
  const [currentUser, setCurrentUser] = useState(null);
  const [stats, setStats] = useState({
    totalBooks: 0,
    target: 100000,
    percentageComplete: 0
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    setCurrentUser(getStoredUser());
    fetchGlobalStats();

    const interval = setInterval(fetchGlobalStats, 30000);
    return () => clearInterval(interval);
  }, []);

  const fetchGlobalStats = async () => {
    try {
      const response = await booksAPI.getGlobalStats();
      setStats(response.data);
    } catch (error) {
      console.error('Error fetching stats:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleStartJourney = () => {
    navigate(currentUser ? '/dashboard' : '/register');
  };

  const handleLoginOrDashboard = () => {
    navigate(currentUser ? '/dashboard' : '/login');
  };

  const handleLogout = () => {
    clearUserSession();
    setCurrentUser(null);
  };

  return (
    <div>
      <div className="header">
        <div className="header-content">
          <h1>AKHSS Kharadar - 100 Years Celebration</h1>
          <p>Gift of Reading Initiative</p>
          <p style={{ fontSize: '0.9rem', marginTop: '5px', fontStyle: 'italic' }}>
            Aligned with the guidance of His Highness the Aga Khan V
          </p>

          {currentUser && (
            <div className="home-session">
              <span>Logged in as {currentUser.firstName}</span>
              <button onClick={() => navigate('/dashboard')} className="btn">
                Dashboard
              </button>
              <button onClick={handleLogout} className="btn btn-secondary">
                Logout
              </button>
            </div>
          )}
        </div>
      </div>

      <div className="container">
        <div className="card" style={{ textAlign: 'center' }}>
          <div className="hero-panel">
            <h2>Join Our Reading Journey</h2>
            <p>
              Be part of history. Help the AKESP community achieve our collective goal
              of completing <strong> 100,000 book readings</strong> to celebrate 100 years
              of educational excellence.
            </p>
          </div>

          <div style={{ marginBottom: '40px' }}>
            <h3 style={{ marginBottom: '20px', color: '#333' }}>
              How It Works
            </h3>
            <div className="steps-grid">
              <div className="step-panel">
                <div className="step-number">1</div>
                <h4>Register</h4>
                <p>Create your account using your B-Form or CNIC number.</p>
              </div>
              <div className="step-panel">
                <div className="step-number">2</div>
                <h4>Read</h4>
                <p>Read books of your choice and enjoy the journey.</p>
              </div>
              <div className="step-panel">
                <div className="step-number">3</div>
                <h4>Record</h4>
                <p>Log each completed book on the portal.</p>
              </div>
              <div className="step-panel">
                <div className="step-number">4</div>
                <h4>Celebrate</h4>
                <p>Watch our community progress toward 100,000 books.</p>
              </div>
            </div>
          </div>

          <div style={{ display: 'flex', gap: '15px', justifyContent: 'center', flexWrap: 'wrap' }}>
            <button
              className="btn"
              onClick={handleStartJourney}
              style={{ fontSize: '1.1rem', padding: '15px 40px' }}
            >
              {currentUser ? 'Continue Journey' : 'Start the Journey'}
            </button>
            <button
              className="btn btn-secondary"
              onClick={handleLoginOrDashboard}
              style={{ fontSize: '1.1rem', padding: '15px 40px' }}
            >
              {currentUser ? 'Open Dashboard' : 'Already Registered? Login'}
            </button>
          </div>
        </div>

        <div className="card">
          <h2 style={{ textAlign: 'center', marginBottom: '30px', color: '#333' }}>
            Pledge Live Tracker
          </h2>

          {loading ? (
            <div className="loading">
              <div className="spinner"></div>
              <p>Loading statistics...</p>
            </div>
          ) : (
            <>
              <div style={{ textAlign: 'center', marginBottom: '30px' }}>
                <div className="tracker-circle">
                  <div style={{ fontSize: '3rem', fontWeight: 'bold' }}>
                    {stats.totalBooks.toLocaleString()}
                  </div>
                  <div style={{ fontSize: '1rem', marginTop: '10px' }}>
                    of {stats.target.toLocaleString()}
                  </div>
                  <div style={{ fontSize: '0.9rem', marginTop: '5px', opacity: 0.9 }}>
                    books read
                  </div>
                </div>
              </div>

              <div style={{ marginBottom: '20px' }}>
                <div className="progress-heading">
                  <span>Progress</span>
                  <span>{stats.percentageComplete}%</span>
                </div>
                <div className="progress-bar">
                  <div
                    className="progress-fill"
                    style={{ width: `${Math.min(stats.percentageComplete, 100)}%` }}
                  >
                    {stats.percentageComplete > 5 && `${stats.percentageComplete}%`}
                  </div>
                </div>
              </div>

              <div className="tracker-note">
                <p>
                  Together, we are making progress.
                  {stats.totalBooks > 0 && ` Join ${stats.totalUsers} readers who have already contributed.`}
                </p>
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
};

export default LandingPage;
